          "stepType": "TextOutput",
          "name": "Item Description",
          "value": [
            {
              "value": "(function execute() {\n    var itemJson = JSON.parse(vaVars.itemJSON);\n    var response = gs.getMessageLang(\"Here are some more details about {0}\", vaContext.getRequesterLang(), [vaVars.itemName]);\n    if (itemJson.description) \n        return response + itemJson.description;\n\n    return gs.getMessageLang(\"Selected {0}\", vaContext.getRequesterLang(), [vaVars.itemName]);\n})()\n",
              "mode": "script"
            }
