        "f9b3f868f4a54c85bb85efb915858fb8": {
          "stepType": "ReferenceChoicePrompt",
          "name": "Question Requested For",
          "prompt": {
            "value": "(function execute() {\n   var quesJson = JSON.parse(vaVars.itemJSON).variables[vaVars.qIndex];\n   var response = quesJson.label;\n   var json = new JSON();\n   var infoKeys = json.getKeys(quesJson.field_info_messages);\n   var warnKeys = json.getKeys(quesJson.field_warn_messages);\n   var errKeys = json.getKeys(quesJson.field_error_messages);\n   \n   for (var j = infoKeys.length - 1; j >= 0; j--) {\n      response +=  \"\\n\" + gs.getMessageLang(\"Info\", vaContext.getRequesterLang()) + \": \" + quesJson.field_info_messages[infoKeys[j]];\n   }\n   for (j = warnKeys.length - 1; j >= 0; j--) {\n      response += \"\\n\" + gs.getMessageLang(\"Warning\", vaContext.getRequesterLang()) + \": \" + quesJson.field_warn_messages[warnKeys[j]];\n   }\n   for (j = errKeys.length - 1; j >= 0; j--) {\n      response += \"\\n\" + gs.getMessageLang(\"Error\", vaContext.getRequesterLang()) + \": \" + quesJson.field_error_messages[errKeys[j]];\n   }\n   return response;\n})()",
            "mode": "script"
          },
          "confirmMessage": {
            "value": "",
            "mode": "simple"
          },
          "acknowledgeMsg": {
            "value": "",
            "mode": "simple"
          },
          "applicability": {
            "value": "",
            "mode": "query"
          },
          "optional": false,
          "defaultValue": {
            "value": "",
            "mode": "simple"
          },
          "variableId": "5a02f855f9584fc8ad57fc779ed10419",
          "id": "f9b3f868f4a54c85bb85efb915858fb8",
          "mode": "external",
          "script": "(function execute() {\n    var options = [];\n    var index = parseInt(vaVars.index);\n    var limit = parseInt(vaVars.limit);\n    var count = 0;\n    var gr = new GlideRecordSecure('sys_user');\n    var quesJson = JSON.parse(vaVars.itemJSON).variables[vaVars.qIndex];\n    gr.addEncodedQuery('nameLIKE'+ vaInputs.search_requested_for);\n    gr.addQuery(quesJson.qualifier);\n    gr.orderBy(gr.getDisplayName());\n    gr.chooseWindow(index, index + limit, true);\n    gr.query();\n\n    var count = gr.getRowCount();\n    vaVars.count = count;\n\n    while (gr.next()) {\n        options.push({\n            \"value\" : gr.getUniqueValue(),\n            \"label\" : gr.getDisplayValue()\n        });\n    }\n\n    if (index > 0) \n        options.push({ 'value': 'prev', 'label': gs.getMessageLang('Show previous', vaContext.getRequesterLang())});\n    if (count > index + limit)\n        options.push({ 'value': 'next', 'label': gs.getMessageLang('Show more', vaContext.getRequesterLang())});\n    \n    if (count > 0) {\n        options.push({\n            'value' : 'search',\n            'label' : gs.getMessageLang('Someone else', vaContext.getRequesterLang())\n        });\n    }\n    return options;    \n})()\n",
          "noRecordsResponseMsg": {
            "value": [
              {
                "type": "paragraph",
                "children": [
