          "id": "f4d8640f9b304943b022ce615426ee82",
          "stepType": "ScriptOutput",
          "name": "Validation Message",
          "output_type": "single_part",
          "script": "(function execute() {\n     var singleOutMsg = new sn_cs.SinglePartOutMsg();\n       singleOutMsg.setTextPart(gs.getMessageLang('{0}. Answer the question again', vaContext.getRequesterLang(), [vaVars.validation_message]));\n       vaVars.validation_message = \"\";\n       return singleOutMsg;\n})()\n",
          "applicability": {
            "value": "",
            "mode": "query"
          }
        },
