          "secure": false,
          "value": [
            {
              "value": "(function execute() {\n    var quesJson = JSON.parse(vaVars.itemJSON).variables[vaVars.qIndex];\n    var renderedValue = quesJson.display_value ? quesJson.display_value : quesJson.value;\n    if (quesJson.type == 7) {\n        renderedValue = quesJson.value == \"true\" ? \"Yes\" : \"No\";\n    }\n    return gs.getMessageLang(\"<b>{0}</b> was selected as the value for <b>{1}</b>\", vaContext.getRequesterLang(), [renderedValue, quesJson.label])\n})()\n",
              "mode": "script"
            }
          ],
          "applicability": {
            "mode": "script",
            "value": "(function execute() {\n    var quesJson = JSON.parse(vaVars.itemJSON).variables[vaVars.qIndex];\n    if (quesJson.type == 7)\n        return quesJson.has_default_value;\n    return quesJson.value ? true : false;\n})()\n"
          },
