          "condition": {
            "value": "(function execute() {\n    var index = parseInt(vaVars.index);\n    var limit = parseInt(vaVars.limit);\n    var options = choices = [];\n    var count = 0;\n    var quesJson = JSON.parse(vaVars.itemJSON).variables[vaVars.qIndex];\n\n    if (quesJson.type == 7)\n        choices = [{ \"label\": gs.getMessageLang(\"Yes\", vaContext.getRequesterLang()), \"value\": \"yes\" }, { \"label\": gs.getMessageLang(\"No\", vaContext.getRequesterLang()), \"value\": \"no\" }];\n    else\n        choices = quesJson.options;\n\n    if (choices.length > 0 && quesJson.mandatory) {\n        if (!choices[0].value)\n            choices.shift();\n    }\n    \n    count = choices.length;\n    vaVars.count = count;\n    options = choices.splice(index, limit);\n\n    if (index > 0) \n        options.push({ 'value': 'prev', 'label': gs.getMessageLang('Show previous', vaContext.getRequesterLang())});\n\n    if (count > index + limit)\n        options.push({ 'value': 'next', 'label': gs.getMessageLang('Show more', vaContext.getRequesterLang())});\n    \n    return options;    \n})()",
